def compute(vars):
    current_assets = vars["v1"]
    prior_assets = vars["v2"]

    if prior_assets == 0:
        return None

    growth_rate = (current_assets - prior_assets) / prior_assets

    return {
        "value": growth_rate,
        "trace": {
            "current_assets": current_assets,
            "prior_assets": prior_assets,
            "change": current_assets - prior_assets,
            "growth_rate": growth_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
